; ============================================================
; function aim (turbo mode)
; ============================================================

p_bul_aim:

			; Bul.cls 797: Dim dx As Integer, dy As Integer, ax As Integer, ay As Integer, t As Integer

			; Bul.cls 798: dx = tx - x : dy = ty - y
			dw kw_subvv, var_bul_aim_tx, var_bul_aim_x, var_bul_aim_dx
			dw kw_subvv, var_bul_aim_ty, var_bul_aim_y, var_bul_aim_dy

			; Bul.cls 799: ax = Abs(dx) : ay = Abs(dy)
			dw kw_absv, var_bul_aim_dx, var_bul_aim_ax
			dw kw_absv, var_bul_aim_dy, var_bul_aim_ay

			; Bul.cls 800: If ax = 0 And ay = 0 Then
			dw kw_cpeqvl, var_bul_aim_ax, 0
			dw kw_ftov, tmp0
			dw kw_cpeqvl, var_bul_aim_ay, 0
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if410_1

			; Bul.cls 801: Aim = 0
			dw kw_ztov, var_bul_aim_aim

			; Bul.cls 802: Exit Function
			dw p_bul_aim_r

			; Bul.cls 803: End If
if410_1:

			; Bul.cls 804: If ax <= ay Then
			dw kw_scplevv, var_bul_aim_ax, var_bul_aim_ay
			dw kw_goto_iffalse, if411_1

			; Bul.cls 805: t = atn(ax * 16 \ ay)
			dw kw_mulvl, var_bul_aim_ax, 16, tmp0
			dw kw_divvv, tmp0, var_bul_aim_ay, tmp0
			dw kw_aget, arr_bul_atn, tmp0, var_bul_aim_t

			; Bul.cls 806: Else
			dw if411_e_go
if411_1:

			; Bul.cls 807: t = 64 - atn(ay * 16 \ ax)
			dw kw_mulvl, var_bul_aim_ay, 16, tmp1
			dw kw_divvv, tmp1, var_bul_aim_ax, tmp1
			dw kw_aget, arr_bul_atn, tmp1, tmp1
			dw kw_sublv, 64, tmp1, var_bul_aim_t

			; Bul.cls 808: End If
if411_e:

			; Bul.cls 809: If dy >= 0 Then
			dw kw_scpgevl, var_bul_aim_dy, 0
			dw kw_goto_iffalse, if412_1

			; Bul.cls 810: If dx >= 0 Then Aim = t Else Aim = (256 - t) And 255
			dw kw_scpgevl, var_bul_aim_dx, 0
			dw kw_goto_iffalse, if413_1
			dw kw_vtov, var_bul_aim_t, var_bul_aim_aim
			dw if412_e_go
if413_1:
			dw kw_sublv, 256, var_bul_aim_t, tmp0
			dw kw_andvl, tmp0, 255, var_bul_aim_aim
if413_e:

			; Bul.cls 811: Else
			dw if412_e_go
if412_1:

			; Bul.cls 812: If dx >= 0 Then Aim = 128 - t Else Aim = 128 + t
			dw kw_scpgevl, var_bul_aim_dx, 0
			dw kw_goto_iffalse, if414_1
			dw kw_sublv, 128, var_bul_aim_t, var_bul_aim_aim
			dw if414_e_go
if414_1:
			dw kw_addl, var_bul_aim_t, 128, var_bul_aim_aim
if414_e:

			; Bul.cls 813: End If
if412_e:
			dw p_bul_aim_r

